package calc

func transform(xs []int64, lo, hi int64) int64 {
	var s int64
	for _, x := range xs {
		if x%2 != 0 {
			x *= 3
		}
		s += min(max(x, lo), hi)
	}
	return s
}

package calc

import "testing"

func TestTransform(t *testing.T) {
	if got := transform([]int64{1, 2, 3, -4}, 0, 5); got != 9 {
		t.Errorf("transform([]int64{1, 2, 3, -4}, 0, 5) = %d, want 9", got)
	}
	if got := transform(nil, 0, 1); got != 0 {
		t.Errorf("transform(nil, 0, 1) = %d, want 0", got)
	}
}
